"""C046 r1: Lean 4 core proof of the realizable-word lemma (general form of K11, basis of K10/K15).
Height semantics. An agent is ANY causal operator A(p,q)(h) (p = opponent's moves against it,
q = opponent's moves against DefectBot; value at h depends on p,q below h). A game with a causal
opponent O is a pair (x,y): x = A(y, O(Z,Z)), y = O(x, A(Z,Z)), Z = all-defect (DefectBot).
Realizable(A,p,q): p(g) = q(g) at every g up to the first height where A(p,q) or A's DefectBot
trace A(Z,Z) cooperates. Theorems (no sorryAx):
  game_exists       every causal agent/opponent pair has a game fixed point;
  inputs_realizable the inputs an agent meets in any game are realizable;
  same_behaviour    equal DefectBot traces + agreement on realizable words => equal moves (both
                    sides) at every height in every game, for every causal opponent;
  separation        a first difference on a realizable word is shown to every game against the
                    explicit causal opponent SepOpp (plays q while its inputs are all-false, else p);
  behaviour_iff     BehEq A A' <-> RealEq A A' for causal A, A';
  X_beheq_FB        instance: X = box(p | (q & box F)) behaves as FairBot (K11 as a corollary).
Scope: opponents here are all causal operators. The <= direction therefore covers every modal
opponent. The => direction's separator SepOpp need not be modal; K10's detector opponents realise
eventually-constant words modally (finite-state agents), not formalised here. Bridge (modal fixed
points = height traces) assumed as in earlier claims. 4 mutations must be rejected.
"""
import subprocess, shutil, os, hashlib
LEAN = "-- Height semantics. An agent is a causal operator A p q h (p = opponent's moves against it,\n-- q = opponent's moves against DefectBot); its move at h depends on p, q below h.\ndef Causal (F : (Nat → Prop) → (Nat → Prop) → Nat → Prop) : Prop :=\n  ∀ a a' b b' h, (∀ g, g < h → ((a g ↔ a' g) ∧ (b g ↔ b' g))) → (F a b h ↔ F a' b' h)\ndef Causal1 (G : (Nat → Prop) → Nat → Prop) : Prop :=\n  ∀ a a' h, (∀ g, g < h → (a g ↔ a' g)) → (G a h ↔ G a' h)\ndef Z : Nat → Prop := fun _ => False\n-- A plays x against O, O plays y against A; DefectBot plays Z, so A's DefectBot trace is A Z Z.\ndef Game (A O : (Nat → Prop) → (Nat → Prop) → Nat → Prop) (x y : Nat → Prop) : Prop :=\n  (∀ h, x h ↔ A y (O Z Z) h) ∧ (∀ h, y h ↔ O x (A Z Z) h)\n-- Realizable input words: p = q at every height up to the first cooperation of A or of its DB trace.\ndef Realizable (A : (Nat → Prop) → (Nat → Prop) → Nat → Prop) (p q : Nat → Prop) : Prop :=\n  ∀ g, (∀ j, j < g → ¬ A p q j ∧ ¬ A Z Z j) → (p g ↔ q g)\ndef BehEq (A A' : (Nat → Prop) → (Nat → Prop) → Nat → Prop) : Prop :=\n  ∀ O, Causal O → ∀ x y x' y', Game A O x y → Game A' O x' y' → ∀ h, x h ↔ x' h\ndef RealEq (A A' : (Nat → Prop) → (Nat → Prop) → Nat → Prop) : Prop :=\n  (∀ h, A Z Z h ↔ A' Z Z h) ∧ ∀ p q, Realizable A p q → ∀ h, (A p q h ↔ A' p q h)\n\ndef iter (G : (Nat → Prop) → Nat → Prop) : Nat → Nat → Prop\n  | 0 => Z\n  | n+1 => G (iter G n)\n\ntheorem iter_step (G : (Nat → Prop) → Nat → Prop) (hG : Causal1 G) :\n    ∀ n g, g < n → (iter G (n+1) g ↔ iter G n g) := by\n  intro n\n  induction n with\n  | zero => intro g hg; omega\n  | succ n ih =>\n    intro g hg\n    show G (iter G (n+1)) g ↔ G (iter G n) g\n    exact hG _ _ g (fun j hj => ih j (by omega))\n\ntheorem iter_stable (G : (Nat → Prop) → Nat → Prop) (hG : Causal1 G) :\n    ∀ k n g, g < n → (iter G (n+k) g ↔ iter G n g) := by\n  intro k\n  induction k with\n  | zero => intro n g _; exact Iff.rfl\n  | succ k ih =>\n    intro n g hg\n    rw [← Nat.add_assoc]\n    exact (iter_step G hG (n+k) g (by omega)).trans (ih n g hg)\n\ntheorem fixpoint_exists (G : (Nat → Prop) → Nat → Prop) (hG : Causal1 G) :\n    ∃ z : Nat → Prop, ∀ h, z h ↔ G z h := by\n  refine ⟨fun h => iter G (h+1) h, ?_⟩\n  intro h\n  show G (iter G h) h ↔ G (fun h => iter G (h+1) h) h\n  apply hG\n  intro j hj\n  have e : h = (j+1) + (h-(j+1)) := by omega\n  have := iter_stable G hG (h-(j+1)) (j+1) j (by omega)\n  rw [← e] at this\n  exact this\n\ntheorem game_exists (A O : (Nat → Prop) → (Nat → Prop) → Nat → Prop)\n    (hA : Causal A) (hO : Causal O) : ∃ x y, Game A O x y := by\n  have hG : Causal1 (fun x => A (O x (A Z Z)) (O Z Z)) := by\n    intro a a' h H\n    apply hA\n    intro g hg\n    exact ⟨hO _ _ _ _ g (fun j hj => ⟨H j (by omega), Iff.rfl⟩), Iff.rfl⟩\n  obtain ⟨x, hx⟩ := fixpoint_exists _ hG\n  exact ⟨x, O x (A Z Z), hx, fun _ => Iff.rfl⟩\n\n/-- The inputs an agent meets in any game are realizable. -/\ntheorem inputs_realizable (A O : (Nat → Prop) → (Nat → Prop) → Nat → Prop) (hO : Causal O)\n    (x y : Nat → Prop) (G : Game A O x y) : Realizable A y (O Z Z) := by\n  intro g pre\n  rw [G.2 g]\n  apply hO\n  intro j hj\n  exact ⟨⟨fun e => (pre j hj).1 ((G.1 j).1 e), fun e => False.elim e⟩,\n         ⟨fun e => (pre j hj).2 e, fun e => False.elim e⟩⟩\n\n/-- Agreement on realizable words and equal DefectBot traces give equal moves in every game. -/\ntheorem same_behaviour (A A' O : (Nat → Prop) → (Nat → Prop) → Nat → Prop)\n    (hA' : Causal A') (hO : Causal O) (R : RealEq A A')\n    (x y x' y' : Nat → Prop) (G : Game A O x y) (G' : Game A' O x' y') :\n    ∀ h, (x h ↔ x' h) ∧ (y h ↔ y' h) := by\n  have real := inputs_realizable A O hO x y G\n  have P : ∀ n, ∀ g, g < n → ((x g ↔ x' g) ∧ (y g ↔ y' g)) := by\n    intro n\n    induction n with\n    | zero => intro g hg; omega\n    | succ n ih =>\n      intro g hg\n      rcases Nat.lt_succ_iff_lt_or_eq.mp hg with hlt | heq\n      · exact ih g hlt\n      · subst heq\n        constructor\n        · rw [G.1 g, G'.1 g, R.2 _ _ real g]\n          exact hA' _ _ _ _ g (fun j hj => ⟨(ih j hj).2, Iff.rfl⟩)\n        · rw [G.2 g, G'.2 g]\n          exact hO _ _ _ _ g (fun j hj => ⟨(ih j hj).1, R.1 j⟩)\n  intro h\n  exact P (h+1) h (by omega)\n\ntheorem least (P : Nat → Prop) (b : Nat) (hb : P b) : ∃ t, P t ∧ ∀ j, j < t → ¬ P j := by\n  classical\n  induction b using Nat.strongRecOn with\n  | ind b ih =>\n    by_cases H : ∃ j, j < b ∧ P j\n    · obtain ⟨j, hj, pj⟩ := H; exact ih j hj pj\n    · exact ⟨b, hb, fun j hj pj => H ⟨j, hj, pj⟩⟩\n\n/-- A realizable word on which A and A' first differ at h is fed to both agents by the causal\nopponent SepOpp p q: it plays q while both its inputs are all-false so far, and p afterwards. -/\ndef SepOpp (p q : Nat → Prop) (a b : Nat → Prop) (g : Nat) : Prop :=\n  ((∀ j, j < g → ¬ a j ∧ ¬ b j) ∧ q g) ∨ (¬ (∀ j, j < g → ¬ a j ∧ ¬ b j) ∧ p g)\n\ntheorem sep_causal (p q : Nat → Prop) : Causal (SepOpp p q) := by\n  intro a a' b b' h H\n  have e : (∀ j, j < h → ¬ a j ∧ ¬ b j) ↔ (∀ j, j < h → ¬ a' j ∧ ¬ b' j) := by\n    constructor\n    · intro K j hj; rw [← (H j hj).1, ← (H j hj).2]; exact K j hj\n    · intro K j hj; rw [(H j hj).1, (H j hj).2]; exact K j hj\n  unfold SepOpp; rw [e]\n\ntheorem separation (A A' : (Nat → Prop) → (Nat → Prop) → Nat → Prop)\n    (hA : Causal A) (hA' : Causal A') (dt : ∀ h, A Z Z h ↔ A' Z Z h)\n    (p q : Nat → Prop) (rp : Realizable A p q) (h : Nat)\n    (below : ∀ g, g < h → (A p q g ↔ A' p q g)) (diff : ¬ (A p q h ↔ A' p q h)) :\n    Game A (SepOpp p q) (A p q) p ∧\n    ∀ x' y', Game A' (SepOpp p q) x' y' → ¬ (x' h ↔ A p q h) := by\n  classical\n  have dq : ∀ g, SepOpp p q Z Z g ↔ q g := by\n    intro g; unfold SepOpp Z\n    constructor\n    · intro H; rcases H with ⟨_, e⟩ | ⟨n, _⟩\n      · exact e\n      · exact False.elim (n (fun _ _ => ⟨id, id⟩))\n    · intro e; exact Or.inl ⟨fun _ _ => ⟨id, id⟩, e⟩\n  have hq : SepOpp p q Z Z = q := funext (fun g => propext (dq g))\n  have sep_eq : ∀ g, (∀ j, j < g → (A p q j ↔ A' p q j)) → (∀ a, (∀ j, j < g → (a j ↔ A p q j)) →\n      (SepOpp p q a (A' Z Z) g ↔ p g)) := by\n    intro g bel a ha\n    unfold SepOpp\n    by_cases C : ∀ j, j < g → ¬ a j ∧ ¬ A' Z Z j\n    · have C' : ∀ j, j < g → ¬ A p q j ∧ ¬ A Z Z j := fun j hj =>\n        ⟨fun e => (C j hj).1 ((ha j hj).2 e), fun e => (C j hj).2 ((dt j).1 e)⟩\n      have pq := rp g C'\n      constructor\n      · intro H; rcases H with ⟨_, e⟩ | ⟨n, _⟩\n        · exact pq.2 e\n        · exact False.elim (n C)\n      · intro e; exact Or.inl ⟨C, pq.1 e⟩\n    · constructor\n      · intro H; rcases H with ⟨c, _⟩ | ⟨_, e⟩\n        · exact False.elim (C c)\n        · exact e\n      · intro e; exact Or.inr ⟨C, e⟩\n  constructor\n  · constructor\n    · intro g; rw [hq]\n    · intro g\n      unfold SepOpp\n      by_cases C : ∀ j, j < g → ¬ A p q j ∧ ¬ A Z Z j\n      · have pq := rp g C\n        constructor\n        · intro e; exact Or.inl ⟨C, pq.1 e⟩\n        · intro H; rcases H with ⟨_, e⟩ | ⟨n, _⟩\n          · exact pq.2 e\n          · exact False.elim (n C)\n      · constructor\n        · intro e; exact Or.inr ⟨C, e⟩\n        · intro H; rcases H with ⟨c, _⟩ | ⟨_, e⟩\n          · exact False.elim (C c)\n          · exact e\n  · intro x' y' G'\n    have P : ∀ n, n ≤ h → ∀ g, g < n → ((x' g ↔ A' p q g) ∧ (y' g ↔ p g)) := by\n      intro n\n      induction n with\n      | zero => intro _ g hg; omega\n      | succ n ih =>\n        intro hn g hg\n        rcases Nat.lt_succ_iff_lt_or_eq.mp hg with hlt | heq\n        · exact ih (by omega) g hlt\n        · subst heq\n          have yg : y' g ↔ p g := by\n            rw [G'.2 g]\n            exact sep_eq g (fun j hj => below j (by omega)) x'\n              (fun j hj => ((ih (by omega) j hj).1).trans (below j (by omega)).symm)\n          refine ⟨?_, yg⟩\n          rw [G'.1 g, hq]\n          exact hA' _ _ _ _ g (fun j hj => ⟨(ih (by omega) j hj).2, Iff.rfl⟩)\n    have yh : ∀ g, g < h → (y' g ↔ p g) := fun g hg => (P h (Nat.le_refl h) g hg).2\n    have xh : x' h ↔ A' p q h := by\n      rw [G'.1 h, hq]\n      exact hA' _ _ _ _ h (fun j hj => ⟨yh j hj, Iff.rfl⟩)\n    intro e\n    exact diff (e.symm.trans xh)\n\n/-- Behavioural equality against all causal opponents is exactly equal DefectBot traces plus\nagreement on realizable words. -/\ntheorem behaviour_iff (A A' : (Nat → Prop) → (Nat → Prop) → Nat → Prop)\n    (hA : Causal A) (hA' : Causal A') : BehEq A A' ↔ RealEq A A' := by\n  classical\n  constructor\n  · intro B\n    have dt : ∀ h, A Z Z h ↔ A' Z Z h := by\n      have hDB : Causal (fun _ _ => Z) := fun _ _ _ _ _ _ => Iff.rfl\n      have GA : Game A (fun _ _ => Z) (A Z Z) Z := ⟨fun _ => Iff.rfl, fun _ => Iff.rfl⟩\n      have GA' : Game A' (fun _ _ => Z) (A' Z Z) Z := ⟨fun _ => Iff.rfl, fun _ => Iff.rfl⟩\n      exact B _ hDB _ _ _ _ GA GA'\n    refine ⟨dt, ?_⟩\n    intro p q rp h\n    apply Classical.byContradiction\n    intro nd\n    obtain ⟨t, dtt, lt⟩ := least (fun g => ¬ (A p q g ↔ A' p q g)) h nd\n    have below : ∀ g, g < t → (A p q g ↔ A' p q g) := fun g hg =>\n      Classical.byContradiction (lt g hg)\n    obtain ⟨S1, S2⟩ := separation A A' hA hA' dt p q rp t below dtt\n    obtain ⟨x', y', G'⟩ := game_exists A' (SepOpp p q) hA' (sep_causal p q)\n    exact S2 x' y' G' (B _ (sep_causal p q) _ _ _ _ S1 G' t).symm\n  · intro R O hO x y x' y' G G' h\n    exact (same_behaviour A A' O hA' hO R x y x' y' G G' h).1\n\n#print axioms behaviour_iff\n#print axioms same_behaviour\n#print axioms game_exists\n\n-- Instance (K11 as a corollary): X = box(p ∨ (q ∧ box ⊥)) and FairBot = box p.\ndef FBa (p _q : Nat → Prop) (h : Nat) : Prop := ∀ g, g < h → p g\ndef Xa (p q : Nat → Prop) (h : Nat) : Prop := ∀ g, g < h → (p g ∨ (q g ∧ g = 0))\ntheorem X_realeq_FB : RealEq FBa Xa := by\n  constructor\n  · intro h; unfold FBa Xa Z\n    constructor\n    · intro H g hg; exact absurd (H g hg) id\n    · intro H g hg; rcases H g hg with e | ⟨e, _⟩ <;> exact e\n  · intro p q rp h\n    have r0 : p 0 ↔ q 0 := rp 0 (fun j hj => absurd hj (Nat.not_lt_zero j))\n    unfold FBa Xa\n    constructor\n    · intro H g hg; exact Or.inl (H g hg)\n    · intro H g hg\n      rcases H g hg with e | ⟨e, g0⟩\n      · exact e\n      · subst g0; exact r0.2 e\ntheorem X_beheq_FB : BehEq FBa Xa :=\n  (behaviour_iff FBa Xa (fun a a' b b' h H => by\n      unfold FBa; exact ⟨fun K g hg => ((H g hg).1).1 (K g hg), fun K g hg => ((H g hg).1).2 (K g hg)⟩)\n    (fun a a' b b' h H => by\n      unfold Xa\n      constructor\n      · intro K g hg; rcases K g hg with e | ⟨e, z⟩\n        · exact Or.inl (((H g hg).1).1 e)\n        · exact Or.inr ⟨((H g hg).2).1 e, z⟩\n      · intro K g hg; rcases K g hg with e | ⟨e, z⟩\n        · exact Or.inl (((H g hg).1).2 e)\n        · exact Or.inr ⟨((H g hg).2).2 e, z⟩)).2 X_realeq_FB\n#print axioms X_beheq_FB\n"
assert hashlib.sha256(LEAN.encode()).hexdigest() == '725e28ce1a8a6fec4291684f0b555af50c607cd6fede5db0491122692a763e41'
binary = next((p for p in (shutil.which('lean'), '/opt/elan/bin/lean', os.path.expanduser('~/.elan/bin/lean')) if p and os.path.exists(p)), None)
assert binary, 'lean missing'
def run(src):
    return subprocess.run([binary, '--stdin'], input=src, text=True, capture_output=True, timeout=100)
r = run(LEAN)
assert r.returncode == 0, r.stdout + r.stderr
assert 'sorryAx' not in r.stdout, r.stdout
for t in ('behaviour_iff', 'same_behaviour', 'game_exists', 'X_beheq_FB'):
    assert "'%s' depends on axioms" % t in r.stdout, t
mutations = [
    ("(∀ j, j < g → ¬ A p q j ∧ ¬ A Z Z j) → (p g ↔ q g)", "(∀ j, j < g → ¬ A p q j) → (p g ↔ q g)"),
    ("(∀ h, A Z Z h ↔ A' Z Z h) ∧ ∀ p q, Realizable", "∀ p q, Realizable"),
    ("(∀ g, g < h → ((a g ↔ a' g) ∧ (b g ↔ b' g))) → (F a b h", "(∀ g, g ≤ h → ((a g ↔ a' g) ∧ (b g ↔ b' g))) → (F a b h"),
    ("((∀ j, j < g → ¬ a j ∧ ¬ b j) ∧ q g) ∨", "((∀ j, j < g → ¬ a j) ∧ q g) ∨"),
]
for a, b in mutations:
    assert LEAN.count(a) == 1, a
    m = run(LEAN.replace(a, b))
    assert m.returncode != 0 or 'sorryAx' in m.stdout, ('mutation accepted', b)
print('PASS: behaviour_iff, same_behaviour, separation, game_exists, X_beheq_FB proved (no sorry); 4 mutations rejected')
